styles:
body {
    font-family: 'Roboto Condensed', sans-serif;
    line-height: 1.6;
    color: #FFFFFF;
    margin: 0;
    padding: 0;
    background-color: #000000;
}
.container {
    max-width: 900px;
    margin: 20px auto;
    padding: 20px 30px;
}
h1, h2, h3, h4 {
    color: #FFFFFF;
    font-weight: 700;
    text-transform: uppercase;
    font-family: 'Roboto Condensed', sans-serif;
}
h1 {
    font-size: 2.5em;
    border-bottom: 3px solid #330000;
    padding-bottom: 15px;
    margin-bottom: 25px;
    text-align: center;
    letter-spacing: 1px;
}
h2 {
    font-size: 1.8em;
    margin-top: 30px;
    border-left: 5px solid #cc0000;
    padding-left: 10px;
}
h3 {
    font-size: 1.3em;
    margin-top: 20px;
    color: #ff3333;
}
p {
    margin-bottom: 15px;
    color: #FFFFFF;
}
a {
    color: #ffaa33;
    text-decoration: none;
}
a:hover {
    color: #ffd077;
    text-decoration: underline;
}
div.xem-them {
    display: block;
    box-sizing: border-box;
    width: 100%;
    background-color: #1a1200;
    border-top: 1px solid #7a5500;
    border-right: 1px solid #7a5500;
    border-bottom: 1px solid #7a5500;
    border-left: 4px solid #ffaa33;
    border-radius: 4px;
    padding: 11px 16px;
    margin: 20px 0 24px 0;
    font-family: 'Roboto Condensed', sans-serif;
    font-size: 0.95em;
    font-weight: 700;
    color: #ffaa33;
    letter-spacing: 0.4px;
    text-transform: uppercase;
    line-height: 1.5;
}
div.xem-them a {
    color: #ffcc77;
    text-decoration: none;
    font-weight: 400;
    text-transform: none;
    letter-spacing: 0;
}

/* ----------------------------------------------------------------
   SPEC LIST — checklist-style bullets for "Cấu hình khuyến nghị"
---------------------------------------------------------------- */
ul {
    list-style: none;
    padding-left: 0;
    margin: 14px 0 20px 0;
}
ul li {
    position: relative;
    padding: 7px 14px 7px 32px;
    margin-bottom: 5px;
    background-color: #0d0d0d;
    border: 1px solid #221010;
    border-left: 3px solid #ffaa33;
    border-radius: 4px;
    color: #f0f0f0;
    font-size: 0.94em;
}
ul li::before {
    content: "\25B8";
    position: absolute;
    left: 11px;
    top: 7px;
    color: #ffaa33;
    font-weight: 700;
    font-size: 1.05em;
}
